<script>window.TI_CSRF=<?=json_encode($_SESSION['csrf'])?>;</script><script src="web-api.js"></script><script src="sessions.js"></script><script src="ob-patterns.js?v=20261107c"></script><script src="break-study.js?v=1"></script><script src="scenario-recap.js?v=1"></script><script src="sequence-trades.js?v=recap1"></script><script src="sequence-report.js?v=recap1"></script><script src="research-desk.js?v=20261108"></script><script src="release-lab.js?v=sequence1"></script><script src="swing-study.js?v=desk-20261108"></script><script src="overlays-v2.js?v=sequence1"></script><script src="session-stats.js?v=20261107c"></script><script src="advanced-study.js?v=desk-20261108"></script><script src="trade-review.js?v=3"></script><script>
const $=id=>document.getElementById(id);let candles=[],results=[],offset=0,count=150,lo=0,hi=1;
function query(ids){return new URLSearchParams(ids.map(id=>[id,$(id).value]));}
async function api(path){const r=await fetch(path),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);return d;}
async function loadChart(){try{$('message').textContent='Loading selected window…';let requestedTF=+$('tf').value;let d=await api('/api/candles?'+query(['start','end','tf']));window.LabLoadedTF=requestedTF;candles=d.candles;$('scrub').max=Math.max(0,candles.length-1);$('scrub').value=0;draw();$('message').textContent=`${d.source_rows.toLocaleString()} source rows → ${candles.length.toLocaleString()} chart bars. Aggregated bars may be partial at missing data or window edges.`;}catch(e){$('message').textContent=e.message;}}
function draw(){let el=$('chart'),rect=el.getBoundingClientRect(),scale=devicePixelRatio||1;el.width=rect.width*scale;el.height=440*scale;let ctx=el.getContext('2d');ctx.scale(scale,scale);let w=rect.width,h=440;ctx.fillStyle='#192334';ctx.fillRect(0,0,w,h);offset=+$('scrub').value;count=Math.max(30,Math.min(1000,+$('zoom').value||150));let a=candles.slice(offset,offset+count);if(!a.length)return;lo=Math.min(...a.map(b=>b[3]));hi=Math.max(...a.map(b=>b[2]));for(const v of [...TradeReview.extents(a),...SequenceTrades.extents(a)]){lo=Math.min(lo,v);hi=Math.max(hi,v);}let pad=Math.max(1,(hi-lo)*.05);lo-=pad;hi+=pad;lo+=el.priceShift||0;hi+=el.priceShift||0;let y=v=>20+(hi-v)/(hi-lo)*330,dx=(w-80)/a.length;ctx.font='11px system-ui';for(let j=0;j<6;j++){let v=lo+(hi-lo)*j/5;ctx.strokeStyle='#304058';ctx.beginPath();ctx.moveTo(0,y(v));ctx.lineTo(w-65,y(v));ctx.stroke();ctx.fillStyle='#b5c7db';ctx.fillText(v.toFixed(2),w-64,y(v));}let maxV=Math.max(1,...a.map(b=>b[5]));a.forEach((b,i)=>{let x=i*dx+dx/2;ctx.strokeStyle=ctx.fillStyle=b[4]>=b[1]?'#24c9ac':'#fa6677';ctx.beginPath();ctx.moveTo(x,y(b[2]));ctx.lineTo(x,y(b[3]));ctx.stroke();ctx.fillRect(x-dx*.35,Math.min(y(b[1]),y(b[4])),Math.max(1,dx*.7),Math.max(1,Math.abs(y(b[1])-y(b[4]))));ctx.globalAlpha=.5;ctx.fillRect(x-dx*.35,402-b[5]/maxV*42,Math.max(1,dx*.7),b[5]/maxV*42);ctx.globalAlpha=1;});ctx.fillStyle='#bccbdf';ctx.textAlign='center';let step=Math.max(1,Math.ceil(a.length/Math.max(2,Math.floor((w-80)/82))));for(let i=0;i<a.length;i+=step){ctx.fillText(a[i][0].slice(11,16),(i+.5)*dx,427);}ctx.textAlign='left';ctx.fillText('ET',w-65,427);TradeReview.draw(ctx,a,dx,y,w);$('window').textContent=`${a[0][0]} — ${a.at(-1)[0]} ET · drag slider to pan`;
}
const drawCandles=draw;
draw=function(){drawCandles();if($('sessions').value==='off')return;let a=candles.slice(offset,offset+count);if(!a.length)return;let el=$('chart'),w=el.getBoundingClientRect().width,ctx=el.getContext('2d'),dx=(w-80)/a.length;ctx.font='10px system-ui';for(let day of new Set(a.map(b=>b[0].slice(0,10))))for(let s of LabSessions.forDay(day)){let stamp=s.time,tf=(window.LabLoadedTF||+$('tf').value),idx=a.findIndex(b=>b[0]<=stamp&&Date.parse(stamp+'Z')<Date.parse(b[0]+'Z')+tf*60000);if(idx<0)continue;let x=idx*dx+dx/2;ctx.strokeStyle=ctx.fillStyle=s.color;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(x,20);ctx.lineTo(x,425);ctx.stroke();ctx.setLineDash([]);ctx.fillText(s.name,x+3,12);}};
const drawWithSessions=draw;
draw=function(){drawWithSessions();let a=candles.slice(offset,offset+count);if(!a.length)return;let w=$('chart').getBoundingClientRect().width;LabOverlays.draw($('chart').getContext('2d'),candles,(window.LabLoadedTF||+$('tf').value),offset,offset+a.length-1,i=>(i-offset+.5)*(w-80)/a.length,v=>20+(hi-v)/(hi-lo)*330);LabSessionStats.draw($('chart').getContext('2d'),candles,(window.LabLoadedTF||+$('tf').value),offset,offset+a.length-1,i=>(i-offset+.5)*(w-80)/a.length,v=>20+(hi-v)/(hi-lo)*330);};
window.addEventListener('lab-overlays',draw);
$('chart').onmousemove=e=>{let r=$('chart').getBoundingClientRect(),a=candles.slice(offset,offset+count),i=Math.floor((e.clientX-r.left)/(r.width-80)*a.length),b=a[i];if(b)$('hover').textContent=`${b[0]} ET | O ${b[1]} H ${b[2]} L ${b[3]} C ${b[4]} | Volume ${b[5]} | ${LabOverlays.describe(candles,(window.LabLoadedTF||+$('tf').value),offset+i)}`;};
window.addEventListener('resize',draw);
async function test(){try{$('message').textContent='Testing selected window…';const reviewWindow={start:$('start').value,end:$('end').value};let d=await api('/api/test?'+query(['start','end','mode','ratio','stopmode','stop','target','hold','cost','slippage'])+'&'+new URLSearchParams({...LabOverlays.query(),...SwingStudy.query(),...ReleaseLab.query(),cgMode:$('cgMode').value,cgVol:$('cgVol').value,trail:$('trail').checked?'1':'0',trigger:$('trigger').value,give:$('give').value,offset:$('offsetPts').value,expiry:$('entryWait').value,n1:$('cg1').value,n3:$('cg3').value}));results=d.trades;let report=$('executionReport');if(!report){report=document.createElement('p');report.id='executionReport';$('stats').after(report);}report.textContent='';if(d.execution){const e=d.execution,m=e.matched,n=e.baseline_stops;const fmt=x=>x+' / '+n+(n?' ('+(100*x/n).toFixed(1)+'%)':'');report.textContent='Original next-open, no trail: '+e.baseline_closed+' closed, '+e.baseline_net+' net pts. Same-signal replay of original stops: profitable '+fmt(m.profitable)+', still lost '+fmt(m.loss)+', flat '+fmt(m.flat)+', unfilled (expired/gap/end) '+fmt(m.expired+m.gap_cancel+m.pending_end)+', invalid stop '+m.invalid_stop+', still open '+m.open_end+'. Actual modified portfolio: '+e.orders.expired+' expired, '+e.orders.gap_cancel+' gap cancellations. Matched replays are independent and may overlap; portfolio trades cannot.';}$('stats').textContent=`${d.detected} patterns · ${d.closed} closed trades · ${d.closed?(100*d.wins/d.closed).toFixed(1):'0'}% wins · ${d.net_points} net pts · ${d.max_closed_drawdown} pts closed-trade drawdown`;$('message').textContent=`${d.ambiguous} ${d.execution?'bars with different high-first/low-first paths; lower marked outcome used':'ambiguous bars treated stop-first'}. ${d.gaps} data discontinuities. ${d.busy} patterns skipped while busy. Open final position: ${d.open_position?'YES':'no'}.`;$('trades').replaceChildren();for(let t of results){let tr=document.createElement('tr');for(let k of ['time','side','entry','exit','net_points','reason','pattern_name']){let td=document.createElement('td');td.textContent=t[k]??'—';tr.append(td);}$('trades').append(tr);}await TradeReview.bind(results,reviewWindow);}catch(e){$('message').textContent=e.message;}}
function download(){if(!results.length)return;let keys=Object.keys(results[0]),s=[keys.join(','),...results.map(r=>keys.map(k=>JSON.stringify(r[k])).join(','))].join('\n'),u=URL.createObjectURL(new Blob([s],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='trades.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
api('/api/meta').then(d=>{$('message').textContent=d.first?`Database available: ${d.first} — ${d.last} ET. Choose a window.`:'Database empty. Open Import CSV to add your data.';if(d.first&&!new URLSearchParams(location.search).has('note')){$('start').value=d.first.slice(0,10);$('end').value=d.first.slice(0,10);}}).catch(e=>$('message').textContent=e.message);
</script><script src="enhance.js?v=desk-20261108"></script><script src="historical-core.js?v=3"></script><script src="historical-ui.js?v=3"></script><script src="swing-levels-ui.js?v=1"></script></html>
